configuration.jsScript:
var t = Number(msg.temp);
if (msg.temp === null || msg.temp === undefined || !isFinite(t)) return false;
var name = String(metadata.deviceName || metadata.originatorName || metadata.name || '').toLowerCase();
if (name.indexOf('industrial') !== -1) return t > 40;
if (name.indexOf('farm') !== -1 || name.indexOf('residential') !== -1) return t > 25;
// Unknown device name: use 30 C rather than applying a zone-specific limit incorrectly.
return t > 30;

